/**
 * Consolidate several source servers onto ONE target. Builds the collision plan
 * and REFUSES (returning the blockers) when sources overlap on ports or paths —
 * those need the verified engine remap step before they can auto-run without risk
 * of one app clobbering another. When there are no such blockers, it creates a
 * migration per source; the serial worker imports them one after another onto the
 * same target. Domain overlaps are allowed (you point DNS where you choose).
 */
export async function startConsolidationMigration(input: {
  serverId: string;
  sources: ConsolidationStartSource[];
}): Promise<{ error?: string; ids?: string[]; blockers?: Collision[]; plan?: ConsolidationPlan }> {
  const { user } = await ownedTargetServer(input.serverId);
  if (!Array.isArray(input.sources) || input.sources.length < 2) {
    return { error: "Add at least two source servers to consolidate." };
  }
  if (input.sources.length > 5) {
    return { error: "You can consolidate up to 5 servers at a time." };
  }
  const rl = checkRateLimit(`migrate:consolidate:${user.id}`, { max: 3, windowMs: 30 * 60 * 1000 });
  if (!rl.ok) return { error: `Slow down — try again in ${rl.retryAfterSec}s.` };

  const plan = planConsolidation(inventoriesForSources(input.sources), {});
  const blockers = consolidationBlockers(plan);
  const portBlk = blockers.filter((b) => b.kind === "port");
  const pathBlk = blockers.filter((b) => b.kind === "path");
  const ex = (arr: Collision[]) => [...new Set(arr.map((b) => b.value))].slice(0, 3).join(", ");

  // Port overlaps can never auto-resolve: two apps cannot share a port, and the
  // app's own bind config is not ours to guess. Always block.
  if (portBlk.length) {
    return { error: `These servers overlap on ports (${ex(portBlk)}). Two apps can't share a port — change one at the source, then consolidate.`, blockers, plan };
  }
  // Path overlaps: the engine copies each colliding path to its OWN directory (no
  // data loss), then reports where it landed so you point the app's config there.
  // Gated behind NXEON_CONSOLIDATE_REMAP until validated on a migration rehearsal.
  const remapEnabled = !!process.env.NXEON_CONSOLIDATE_REMAP && process.env.NXEON_CONSOLIDATE_REMAP !== "0";
  if (pathBlk.length && !remapEnabled) {
    return { error: `These servers overlap on paths (${ex(pathBlk)}). Path auto-remap is behind NXEON_CONSOLIDATE_REMAP until it's validated on a rehearsal — enable it, migrate the overlapping ones one at a time, or change them at the source.`, blockers, plan };
  }

  // Hand each source to the normal migration path (the serial worker sequences the
  // jobs so imports don't race), carrying that source's path remap in items.
  const labels = input.sources.map((s, i) => String(s.label || s.sourceHost || `src-${i + 1}`).slice(0, 40));
  const ids: string[] = [];
  for (let i = 0; i < input.sources.length; i++) {
    const s = input.sources[i];
    const pathRemap: Record<string, string> = {};
    for (const rm of plan.remaps) if (rm.sourceLabel === labels[i] && rm.path) pathRemap[rm.path.from] = rm.path.to;
    const res = await createMigration({ ...s, serverId: input.serverId, pathRemap: Object.keys(pathRemap).length ? pathRemap : undefined });
    if (res.error) return { error: `Source ${s.sourceHost}: ${res.error}`, ids, plan };
    if (res.id) ids.push(res.id);
  }
  return { ids, plan };
}

