export async function createMigration(
  input: CreateMigrationInput
): Promise<{ error?: string; id?: string }> {
  const { user, server } = await ownedTargetServer(input.serverId);

  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
  // credential-stuffing the wizard against arbitrary source hosts.
  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) {
    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
  }

  // Same public-address gate as scanSource — the worker will SSH here.
  const vetted = await vettedSourceHost(input.sourceHost);
  if ("error" in vetted) return { error: vetted.error };
  const host = vetted.host;

  const port = input.sourcePort ?? 22;
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return { error: "SSH port must be between 1 and 65535." };
  }

  const sourceUser = (input.sourceUser ?? "root").trim();
  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
    return { error: "Enter the SSH username on the source server." };
  }

  if (!input.sourcePassword || input.sourcePassword.length < 1) {
    return { error: "Enter the SSH password for the source server." };
  }

  const paths = cleanPaths(input.paths);

  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
  // Databases are auto-included when an engine is detected — no DB password is
  // ever collected; the worker dumps via root's local socket/peer auth.
  const plan = derivePlan(input.scan, paths);

  // Persist the (secret-free) detection snapshot alongside the plan so the
  // migration is traceable back to what auto-detection found. Reusing items
  // avoids a schema change (Migration.items is a Json column).
  const scanSnapshot =
    input.scan && input.scan.ok
      ? {
          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
          homes: input.scan.homes?.slice(0, 40) ?? [],
          databases: input.scan.databases?.slice(0, 60) ?? [],
          engines: input.scan.engines ?? [],
          // Exact engine variant + version — lets the worker install the MATCHING
          // engine on the target for a clean same-engine restore.
          dbEngines: input.scan.dbEngines ?? [],
          // Running-app discovery — informational, secret-free, for traceability.
          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
          containers: input.scan.containers?.slice(0, 30) ?? [],
          ports: input.scan.ports?.slice(0, 60) ?? [],
          services: input.scan.services?.slice(0, 30) ?? [],
          // Storage-guardrail + compatibility inputs (secret-free, for traceability
          // and the worker pre-flight).
          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
          sourceOs: input.scan.sourceOs ?? null,
          sourceArch: input.scan.sourceArch ?? null,
          synthetic: !!input.scan.synthetic,
        }
      : undefined;

  // Trusted server-side total of what will be migrated (bytes) — carried through
  // items so the worker's pre-flight guard can compare it to target free disk
  // without re-scanning. No schema change: Migration.items is a Json column.
  const totalBytes = selectedMigrationBytes(input.scan, paths);

  const items = {
    paths,
    dbEngines: plan.dbEngines,
    dockerVolumes: plan.dockerVolumes,
    composeDirs: plan.composeDirs,
    verifyPorts: plan.verifyPorts,
    hasContainers: plan.hasContainers,
    webServers: plan.webServers,
    runtimes: plan.runtimes,
    totalBytes,
    // Explicit consent only — coerced to a real boolean so nothing else can ride
    // in on this field, and only ever true when the customer ticked the box.
    useVolumeForDocker: input.useVolumeForDocker === true,
    // Consolidation only: source→target path remap so a colliding path lands in
    // its own dir instead of overwriting an earlier source. Absent on normal runs.
    ...(input.pathRemap && Object.keys(input.pathRemap).length ? { remap: { paths: input.pathRemap } } : {}),
    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
  };

  const migration = await db.migration.create({
    data: {
      userId: user.id,
      serverId: server.id,
      sourceHost: host,
      sourcePort: port,
      sourceUser,
      sourcePasswordEnc: encryptSecret(input.sourcePassword),
      items,
      status: "PENDING",
      progress: 0,
      step: "Queued",
    },
  });

  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
  // traceability); the handler loads everything else from payload.migrationId.
  await db.job.create({
    data: {
      type: "MIGRATE",
      serverId: server.id,
      payload: { migrationId: migration.id },
    },
  });

