export type CreateMigrationInput = {
  serverId: string; // target Nxeon server (must be owned by the caller)
  sourceHost: string; // FQDN or IP of the source VPS
  sourcePort?: number; // SSH port, default 22
  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
  sourcePassword: string; // SSH password for the source box
  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
  /**
   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
   * it, and store both the plan and the snapshot under Migration.items — reusing
   * the existing Json column rather than adding a schema field (another agent
   * owns the schema this wave).
   */
  scan?: ScanResult;
  /**
   * Explicit opt-in to use an attached block-storage volume for Docker's stores
   * (`/var/lib/docker` + `/var/lib/containerd`). **Defaults to false.**
   *
   * Volumes are portable: the Volumes UI promises they can be attached to any of
   * the customer's running servers, and their data survives a server rebuild.
   * Mounting a system path on a volume silently ends that — the server can no
   * longer boot properly without it. So this is never inferred from free space;
   * the customer ticks a box in the wizard that says so in as many words. Stored
   * under Migration.items (an existing Json column) — no schema change.
   */
  useVolumeForDocker?: boolean;
  /**
   * Consolidation only: source-path → distinct-target-path map, so a colliding
   * path (two sources both at `/var/www/html`) is copied to its own directory
   * rather than overwriting the earlier source. Set by `startConsolidationMigration`
   * from the collision plan; absent (undefined) on every normal single-source run.
   */
  pathRemap?: Record<string, string>;
};

