export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
  const { migration, target, items, report } = input;
  assert(target, "target server row not found");

  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
  const host = migration.sourceHost;
  const port = migration.sourcePort;
  const user = migration.sourceUser;
  assert(validHost(host), "source host is not a valid hostname or IP address");
  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
  assert(USER_RE.test(user), "source username contains unsupported characters");

  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
  //
  // This used to be a bare `rawPaths.filter(safeCopyTarget)`, which SILENTLY
  // discarded anything the customer had selected. `/home` is in UNSAFE_EXACT and
  // it is also in `DEFAULT_PATHS` (lib/actions-migrate.ts) — so the default
  // selection presented to EVERY customer contained a path this line deleted
  // without a word. Home directories, the single most likely place a customer's
  // actual data lives, were dropped on every migration that used the defaults and
  // nothing anywhere said so.
  //
  // Two changes: `/home` is expanded into its per-user subdirectories once we are
  // connected (safe, because it never overwrites the target's own /home entries),
  // and anything genuinely refused is recorded so it reaches the customer's report
  // instead of vanishing. A selection we decline is a selection we must name.
  const homeSelected = rawPaths.includes("/home");
  const paths = rawPaths.filter((p) => p !== "/home" && safeCopyTarget(p));
  const refusedPaths = rawPaths.filter((p) => p !== "/home" && !safeCopyTarget(p));

  const plan = derivePlan(items);
  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);

  assert(
    homeSelected || paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length,
    "nothing selected to migrate"

  blockers?: PendingItem[];
  /** COMPLETED or COMPLETED_WITH_ISSUES — see MigrationOutcome. */
  outcome?: MigrationOutcome;
  /** Plain-language reasons the outcome is COMPLETED_WITH_ISSUES (empty when clean). */
  outcomeReasons?: string[];
};

