1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { scanSource, planConsolidationMigration, startConsolidationMigration, type ScanResult } from "@/lib/actions-migrate";
5	
6	type ServerOpt = { id: string; name: string };
7	type Row = { host: string; port: string; user: string; password: string; scan?: ScanResult | null; scanError?: string };
8	type Plan = Awaited<ReturnType<typeof planConsolidationMigration>>["plan"];
9	
10	const blank = (): Row => ({ host: "", port: "22", user: "root", password: "" });
11	
12	export function ConsolidateWizard({ servers }: { servers: ServerOpt[] }) {
13	  const [target, setTarget] = useState(servers[0]?.id ?? "");
14	  const [rows, setRows] = useState<Row[]>([blank(), blank()]);
15	  const [plan, setPlan] = useState<Plan | undefined>();
16	  const [blocked, setBlocked] = useState<string | null>(null);
17	  const [msg, setMsg] = useState<string | null>(null);
18	  const [done, setDone] = useState<string[] | null>(null);
19	  const [pending, start] = useTransition();
20	
21	  const setRow = (i: number, patch: Partial<Row>) => setRows((r) => r.map((x, j) => (j === i ? { ...x, ...patch } : x)));
22	  const addRow = () => rows.length < 5 && setRows((r) => [...r, blank()]);
23	  const delRow = (i: number) => rows.length > 2 && setRows((r) => r.filter((_, j) => j !== i));
24	
25	  const review = () =>
26	    start(async () => {
27	      setMsg(null); setBlocked(null); setPlan(undefined); setDone(null);
28	      if (!target) return setMsg("Pick a target server.");
29	      const sources: { label: string; host: string; scan: ScanResult; domains?: string[] }[] = [];
30	      const next = [...rows];
31	      for (let i = 0; i < next.length; i++) {
32	        const r = next[i];
33	        if (!r.host || !r.password) { setMsg("Every source needs a host and SSH password."); return; }
34	        const res = await scanSource({ serverId: target, sourceHost: r.host, sourcePort: Number(r.port) || 22, sourceUser: r.user || "root", sourcePassword: r.password });
35	        if (res.error || !res.scan) { next[i] = { ...r, scanError: res.error ?? "Scan failed" }; setRows([...next]); setMsg(`Couldn't scan ${r.host}: ${res.error ?? "unknown error"}`); return; }
36	        next[i] = { ...r, scan: res.scan, scanError: undefined };
37	        sources.push({ label: r.host, host: r.host, scan: res.scan });
38	      }
39	      setRows(next);
40	      const res = await planConsolidationMigration({ serverId: target, sources });
41	      if (res.error) return setMsg(res.error);
42	      setPlan(res.plan);
43	    });
44	
45	  const run = () =>
46	    start(async () => {
47	      setMsg(null); setBlocked(null);
48	      const sources = rows.filter((r) => r.scan).map((r) => ({ sourceHost: r.host, sourcePort: Number(r.port) || 22, sourceUser: r.user || "root", sourcePassword: r.password, scan: r.scan! }));
49	      const res = await startConsolidationMigration({ serverId: target, sources });
50	      if (res.blockers?.length) { setBlocked(res.error ?? "Overlaps must be resolved first."); setPlan(res.plan); return; }
51	      if (res.error) return setMsg(res.error);
52	      setDone(res.ids ?? []);
53	    });
54	
55	  const hasBlockers = (plan?.collisions ?? []).some((c) => c.kind === "port" || c.kind === "path");
56	
57	  return (
58	    <div className="card">
59	      <h2 className="text-lg font-semibold text-white">Consolidate servers onto one box</h2>
60	      <p className="mt-1 text-sm text-slate-400">Move several source servers onto a single Nxeon server. We scan each one, flag anything that would collide, and run the migrations one after another.</p>
61	
62	      <label className="label mt-5">Target Nxeon server</label>
63	      <select value={target} onChange={(e) => setTarget(e.target.value)} className="input">
64	        {servers.length === 0 && <option value="">No servers yet</option>}
65	        {servers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
66	      </select>
67	
68	      <div className="mt-6 space-y-3">
69	        {rows.map((r, i) => (
70	          <div key={i} className="rounded-xl border border-white/10 bg-white/[0.02] p-4">
71	            <div className="mb-2 flex items-center justify-between">
72	              <span className="text-sm font-medium text-slate-300">Source {i + 1}{r.scan ? " · scanned ✓" : ""}</span>
73	              {rows.length > 2 && <button onClick={() => delRow(i)} className="text-xs text-slate-500 hover:text-red-300">remove</button>}
74	            </div>
75	            <div className="grid gap-2 sm:grid-cols-[1fr_5rem_6rem_1fr]">
76	              <input className="input" placeholder="host or IP" value={r.host} onChange={(e) => setRow(i, { host: e.target.value, scan: null })} />
77	              <input className="input" placeholder="port" value={r.port} onChange={(e) => setRow(i, { port: e.target.value })} />
78	              <input className="input" placeholder="ssh user" value={r.user} onChange={(e) => setRow(i, { user: e.target.value })} />
79	              <input className="input" type="password" placeholder="ssh password" value={r.password} onChange={(e) => setRow(i, { password: e.target.value })} />
80	            </div>
81	            {r.scanError && <p className="mt-2 text-xs text-red-300">{r.scanError}</p>}
82	          </div>
83	        ))}
84	      </div>
85	      <div className="mt-3 flex items-center gap-3">
86	        {rows.length < 5 && <button onClick={addRow} className="btn-secondary text-sm">+ Add source</button>}
87	        <button onClick={review} disabled={pending} className="btn-secondary text-sm">{pending ? "Scanning…" : "Scan & review plan"}</button>
88	      </div>
89	
90	      {msg && <p className="mt-4 rounded-lg border border-amber-400/25 bg-amber-400/[0.06] px-3 py-2 text-sm text-amber-200">{msg}</p>}
91	
92	      {plan && (
93	        <div className="mt-6 rounded-xl border border-white/10 bg-navy-950/40 p-4">
94	          <p className="section-label">Consolidation plan</p>
95	          {plan.collisions.length === 0 ? (
96	            <p className="mt-2 text-sm text-emerald-300">✓ No collisions — these servers merge cleanly. Nothing needs remapping.</p>
97	          ) : (
98	            <ul className="mt-3 space-y-1.5 text-sm">
99	              {plan.collisions.map((c, i) => {
100	                const block = c.kind === "port" || c.kind === "path";
101	                return (
102	                  <li key={i} className={`flex flex-wrap items-center gap-2 ${block ? "text-red-300" : "text-amber-200"}`}>
103	                    <span className="rounded bg-white/10 px-1.5 py-0.5 font-mono text-[11px] uppercase">{c.kind}</span>
104	                    <span className="font-mono">{c.value}</span>
105	                    {c.kind === "port" && c.appName && c.appName.split(":")[0] !== "svc" && (
106	                      <span className="font-mono text-slate-400">({c.appName.split(":")[0]})</span>
107	                    )}
108	                    <span className="text-slate-500">({c.sourceLabel} vs {c.heldBy})</span>
109	                    <span className="text-slate-400">→ {c.remappedTo}</span>
110	                    {block && <span className="text-[11px] font-semibold">needs manual fix</span>}
111	                  </li>
112	                );
113	              })}
114	            </ul>
115	          )}
116	          {hasBlockers && <p className="mt-3 text-xs text-red-300">Port/path overlaps can’t be auto-applied safely yet — resolve them at the source, or migrate those servers one at a time, then consolidate the rest.</p>}
117	          <button onClick={run} disabled={pending || hasBlockers} className="btn-primary mt-4 disabled:opacity-40">{pending ? "Starting…" : "Consolidate now"}</button>
118	        </div>
119	      )}
120	
121	      {blocked && <p className="mt-4 rounded-lg border border-red-500/25 bg-red-500/[0.06] px-3 py-2 text-sm text-red-200">{blocked}</p>}
122	      {done && <p className="mt-4 rounded-lg border border-emerald-400/25 bg-emerald-400/[0.06] px-3 py-2 text-sm text-emerald-200">Started {done.length} migration{done.length === 1 ? "" : "s"} onto your server — they’ll run one after another. Track progress on the Migrate page.</p>}
123	    </div>
124	  );
125	}
